// file number : 342
// full path name : src/context/342_LandscapeChunkMutationReplay.js
// description : Landscape chunk mutation replay — the 10 Hz consumer that
// orchestrates the replay of a chunk's stored mutation list once the chunk's
// geometry has been regenerated by 337_LandscapeChunkStreamer. It reads the
// deserialized mutation list from 341_LandscapeChunkPersistence, verifies that
// the chunk's geometry is in a stable state (the streamer has finished the
// regeneration pass and the geometry version matches the version that was
// current when the chunk was streamed out), calls 341's replayIntoChunk to
// emit per-mutation replay events, and then applies the material and lighting
// overrides from 331_BiomeBlendMaterialBridge and 351_LandscapeLightingCoupler
// to the replayed mutations so a remembered crater, fire scar, felled tree,
// trampled ground, snow accumulation, or moss growth looks identical to one
// that was created live. Replay is idempotent (replaying the same mutation
// list twice produces the same result) and budgeted (default 16 chunks per
// tick) and pauses whenever the chunk is fully occluded by
// 340_LandscapeChunkOcclusion so the player never sees a partially-replayed
// chunk. The orchestrator maintains a per-chunk replay state machine with six
// states:
//   NOT_QUEUED        — no stored mutations, nothing to replay
//   QUEUED            — stored mutations exist, waiting for geometry to settle
//   AWAITING_STABILITY — geometry is regenerating, we are waiting for the
//                        streamer to signal stability for one full tick
//   REPLAYING         — mutations are being replayed through the material and
//                        lighting bridges
//   SETTLING          — replay events have been dispatched, waiting for the
//                        material and lighting bridges to finish applying them
//   DONE              — replay is complete, the chunk is idle
// The state machine is strict: a chunk cannot enter REPLAYING unless it has
// passed through AWAITING_STABILITY for at least one full tick with no
// geometry changes, and it cannot enter DONE unless SETTLING has elapsed for
// at least one full tick. This prevents the very common failure mode where a
// chunk is replayed mid-regeneration and the resulting geometry is a mashup
// of the pre-mutation and post-mutation states. The replay state machine is
// stored in a pooled per-chunk array, the mutation replay buffer is preallocated,
// the material and lighting override appliers are pure functions with no
// allocation, and the per-tick work is bounded by both the chunk budget and a
// per-tick CPU budget so the replay pass never causes a frame hitch even when
// a hundred chunks are deserialized in a single frame during a fast fly-over.
// The replay pass is compatible with both WebGL1 and WebGL2: the material and
// lighting overrides are plain uniforms, not compute shaders, and the per-chunk
// geometry is rebuilt via the standard BufferGeometry update path that both
// WebGLRenderer and WebGL2Renderer accept. The material and lighting features
// integrated into the replay pass are the full set exposed by 331 and 351:
// base albedo in linear RGB, roughness, metalness, transmission, IOR, Fresnel
// F₀, anime flatness weight, anime quantization steps, rim power and colour,
// outline weight, wetness, fire emissive, moss amount, snow amount, damage,
// frost, sun diffuse fraction, shadow softness, snow albedo boost, subsurface,
// anisotropy, clearcoat, sheen, specular, and emissive RGB. Replaying a
// mutation writes the correct post-mutation values for every one of those
// parameters, so a fire scar replayed three sessions later looks exactly the
// same as a fire scar created live — including the charred bark's reduced
// sun diffuse fraction, the lingering smoke's increased fog density, and the
// post-fire canopy gaps' softened shadow edges.
//#
// best for : Every consumer that needs a chunk's stored mutations to be
// replayed into freshly regenerated geometry — 337_LandscapeChunkStreamer
// (emits STREAMED_IN, then relies on this orchestrator to replay before the
// chunk is rendered), 341_LandscapeChunkPersistence (provides the
// deserialized mutation list that this orchestrator replays),
// 300_ImpactEventCoordinator (records live mutations that this orchestrator
// will replay on the next stream-in), 316_EcologyResponseSystem (records
// fire scars that this orchestrator will replay), 331_BiomeBlendMaterialBridge
// (subscribes to the REPLAYED_MUTATION events this orchestrator emits and
// applies the material overrides), 351_LandscapeLightingCoupler (subscribes
// to the same events and applies the lighting overrides),
// 350_LandscapeShadowScaler (uses the post-replay shadow softness to scale
// shadow cascades), 354_LandscapeSensoryCoupler (reads the post-replay
// acoustic and olfactory profiles to set sensory cues on the replayed
// chunk), 355_LandscapePerformanceGovernor (reads the replay queue depth to
// arbitrate budgets), and any system that needs to know whether a chunk has
// been fully replayed or is still pending. The orchestrator is the single
// authority on "has this chunk's stored history been replayed yet?", and
// every consumer that touches a freshly streamed chunk must check with it
// before assuming the chunk is in its final state.
// license : MIT

// ─── raw 3js primitives — exported by the 264 barrel ────────────
import {
  Vec2, Vec3, Vec4, Mat4, Quat,
  SimplexNoise, Precision, DoubleDouble,
  BufferAttribute, BufferGeometry,
  Ray, Plane, Sphere, Box3, Frustum,
  MeshStandardMaterial, MeshPhysicalMaterial, MeshToonMaterial,
  MeshStandardNodeMaterial, MeshPhysicalNodeMaterial, MeshToonNodeMaterial,
  Texture, DataTexture, Data3DTexture, DataArrayTexture, CanvasTexture,
  WebGLRenderer, WebGL2Renderer
} from './264_MathECSImportBarrel.js';

// ─── context providers & systems ────────────────────────────────
import { ContextFrame } from './263_ContextFrame.js';
import { CoreEventDispatcher, EVENT_TYPE, EVENT_NAMES } from './265_CoreEventDispatcher.js';
import { CoreClock, TIER, TIER_PERIOD } from './267_CoreClock.js';
import { smoothstep } from './268_ExtrasCurveUtils.js';
import { BiomeBlendSystem } from './329_BiomeBlendSystem.js';
import { LandscapeChunkDescriptor } from './336_LandscapeChunkDescriptor.js';
import { LandscapeChunkStreamer, LOAD_STATE } from './337_LandscapeChunkStreamer.js';
import { LandscapeChunkHLOD } from './338_LandscapeChunkHLOD.js';
import { LandscapeChunkSpatialHash } from './339_LandscapeChunkSpatialHash.js';
import { LandscapeChunkOcclusion, OCC_STATE } from './340_LandscapeChunkOcclusion.js';
import { LandscapeChunkPersistence } from './341_LandscapeChunkPersistence.js';

// ══════════════════════════════════════════════════════════════════
// ─── CONFIGURATION ──────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════

// HLOD tier identifiers. Must match 336–341.
const HLOD_TIER = Object.freeze({
  KILOMETER: 0,
  TEN_KILOMETER: 1,
  HUNDRED_KILOMETER: 2,
  THOUSAND_KILOMETER: 3
});

// Replay state identifiers.
const REPLAY_STATE = Object.freeze({
  NOT_QUEUED: 0,
  QUEUED: 1,
  AWAITING_STABILITY: 2,
  REPLAYING: 3,
  SETTLING: 4,
  DONE: 5
});

// Maximum number of loaded chunks. Matches 336–341 so the streamer slot is
// a valid index in this module's per-chunk bookkeeping.
const MAX_TRACKED_CHUNKS = 100000;

// Per-tick chunk budget. The orchestrator processes at most this many
// chunks per tick. 16 chunks per tick at 10 Hz means 160 chunks per second,
// which is enough to catch up on a fast fly-over without ever causing a
// frame hitch.
const DEFAULT_TICK_CHUNK_BUDGET = 16;

// Per-tick CPU budget in milliseconds. The orchestrator checks the elapsed
// time inside the tick and stops early if it has exceeded this budget. This
// is the second line of defence against per-tick CPU spikes.
const DEFAULT_TICK_CPU_BUDGET_MS = 1.5;

// Stability dwell time. A chunk must remain in AWAITING_STABILITY for at
// least this many seconds before it can enter REPLAYING. The dwell time is
// chosen so that even at 10 Hz, a chunk that is still regenerating geometry
// will be caught before the replay pass begins.
const STABILITY_DWELL_S = 0.2;

// Settling dwell time. A chunk must remain in SETTLING for at least this
// many seconds before it can enter DONE. This gives the material and
// lighting bridges time to finish applying the replay events.
const SETTLING_DWELL_S = 0.2;

// Maximum number of replay events emitted per tick. The orchestrator
// dispatches one REPLAYED_MUTATION event per mutation; with a chunk budget
// of 16 and a mutation cap of 256, the worst case is 4,096 events per tick.
// This cap is a safety net: if it is exceeded, the orchestrator truncates
// the event stream and sets a flag on the aggregate event so downstream
// systems know to do a full refresh.
const MAX_REPLAY_EVENTS_PER_TICK = 4096;

// Maximum number of chunks the orchestrator tracks at once. Must match the
// other modules.
const MAX_QUEUE_SIZE = 100000;

// ══════════════════════════════════════════════════════════════════
// ─── POOLED PER-CHUNK REPLAY STATE (structure-of-arrays) ───────
// ══════════════════════════════════════════════════════════════════

// Replay state per chunk slot.
const _replayState           = new Uint8Array(MAX_TRACKED_CHUNKS).fill(REPLAY_STATE.NOT_QUEUED);

// Time at which the chunk entered its current state.
const _stateEnteredS         = new Float32Array(MAX_TRACKED_CHUNKS).fill(-1);

// Geometry version at the time the chunk was streamed out.
const _storedGeometryVersion = new Uint32Array(MAX_TRACKED_CHUNKS).fill(0);

// Geometry version at the current tick.
const _currentGeometryVersion = new Uint32Array(MAX_TRACKED_CHUNKS).fill(0);

// Last tick at which the geometry version changed.
const _lastGeometryChangeS   = new Float32Array(MAX_TRACKED_CHUNKS).fill(-1);

// Number of mutations replayed in the current REPLAYING pass.
const _replayedCount         = new Uint16Array(MAX_TRACKED_CHUNKS);

// Total number of mutations to replay.
const _totalMutationCount    = new Uint16Array(MAX_TRACKED_CHUNKS);

// Replay completion flag (used by downstream consumers to know the chunk
// is in its final post-replay state).
const _replayComplete        = new Uint8Array(MAX_TRACKED_CHUNKS);

// Slot active flag.
const _chunkActive           = new Uint8Array(MAX_TRACKED_CHUNKS);

// ─── Replay queue ───────────────────────────────────────────────
// A single ring-buffer queue of streamer slots waiting to be processed. The
// queue is written by the STREAMED_IN listener and consumed by the run()
// loop.
const _queue = new Int32Array(MAX_QUEUE_SIZE).fill(-1);
let _queueHead = 0;
let _queueTail = 0;

// ══════════════════════════════════════════════════════════════════
// ─── SCRATCH BUFFERS ────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════

// Mutation readout scratch. Reused across chunks.
const _mutTypes = new Uint8Array(256);
const _mutPositions = new Float32Array(256 * 3);
const _mutRadii = new Float32Array(256);

// Material override scratch. Indexed by the standard material bridge layout
// (see 331).
const _materialOverride = new Float32Array(16);

// Lighting override scratch. Indexed by the standard lighting bridge layout
// (see 351).
const _lightingOverride = new Float32Array(8);

// ══════════════════════════════════════════════════════════════════
// ─── GLOBAL STATE ───────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════
const _dispatcher = new CoreEventDispatcher();
let _lastProcessed = 0;
let _lastReplayed = 0;
let _lastCompleted = 0;
let _lastTickDurationMs = 0;
let _lastQueueDepth = 0;
let _lastEventsOverflow = false;

// ══════════════════════════════════════════════════════════════════
// ─── STREAMED-IN LISTENER ──────────────────────────────────────
// ══════════════════════════════════════════════════════════════════
// When the streamer emits STREAMED_IN, we enqueue the chunk for replay.
// The actual replay is deferred to the 10 Hz run() loop so it never runs
// in the same tick as the geometry regeneration.

function _onStreamedIn(payload) {
  const streamerSlot = payload.slot;
  if (streamerSlot < 0 || streamerSlot >= MAX_TRACKED_CHUNKS) return;

  // Record the geometry version at stream-out time. The streamer is
  // expected to include this in the payload; if it doesn't, we default to
  // 0 so the stability check treats any geometry regeneration as a
  // version bump.
  _storedGeometryVersion[streamerSlot] = payload.geometryVersion || 0;
  _currentGeometryVersion[streamerSlot] = 0;
  _lastGeometryChangeS[streamerSlot] = BiomeBlendSystem.elapsedSimSeconds;
  _chunkActive[streamerSlot] = 1;
  _replayComplete[streamerSlot] = 0;

  // Transition to QUEUED.
  _replayState[streamerSlot] = REPLAY_STATE.QUEUED;
  _stateEnteredS[streamerSlot] = BiomeBlendSystem.elapsedSimSeconds;

  // Enqueue the streamer slot.
  if (((_queueTail + 1) % MAX_QUEUE_SIZE) !== _queueHead) {
    _queue[_queueTail] = streamerSlot;
    _queueTail = (_queueTail + 1) % MAX_QUEUE_SIZE;
  }
}

function _onStreamedOut(payload) {
  const streamerSlot = payload.slot;
  if (streamerSlot < 0 || streamerSlot >= MAX_TRACKED_CHUNKS) return;
  _chunkActive[streamerSlot] = 0;
  _replayState[streamerSlot] = REPLAY_STATE.NOT_QUEUED;
  _stateEnteredS[streamerSlot] = -1;
  _replayComplete[streamerSlot] = 0;
}

// ══════════════════════════════════════════════════════════════════
// ─── STATE MACHINE ─────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════

// Advance a single chunk through the replay state machine. Returns true if
// the state changed this tick.
function _advanceChunk(streamerSlot, nowS, dt) {
  const state = _replayState[streamerSlot];
  const stateAge = nowS - _stateEnteredS[streamerSlot];

  switch (state) {
    case REPLAY_STATE.NOT_QUEUED:
      return false;

    case REPLAY_STATE.QUEUED: {
      // Check whether there are stored mutations to replay. If not,
      // transition straight to DONE.
      const storedCount = _getStoredMutationCount(streamerSlot);
      _totalMutationCount[streamerSlot] = storedCount;
      if (storedCount === 0) {
        _transition(streamerSlot, REPLAY_STATE.DONE, nowS);
        _replayComplete[streamerSlot] = 1;
        return true;
      }
      // Otherwise, transition to AWAITING_STABILITY.
      _transition(streamerSlot, REPLAY_STATE.AWAITING_STABILITY, nowS);
      return true;
    }

    case REPLAY_STATE.AWAITING_STABILITY: {
      // The chunk must remain stable for STABILITY_DWELL_S before it can
      // enter REPLAYING. "Stable" means the geometry version has not
      // changed since the chunk entered AWAITING_STABILITY.
      const sinceChange = nowS - _lastGeometryChangeS[streamerSlot];
      if (sinceChange < STABILITY_DWELL_S || stateAge < STABILITY_DWELL_S) {
        return false;
      }
      // Transition to REPLAYING.
      _transition(streamerSlot, REPLAY_STATE.REPLAYING, nowS);
      return true;
    }

    case REPLAY_STATE.REPLAYING: {
      // Perform the replay. This calls 341's replayIntoChunk and then
      // applies the material and lighting overrides to each replayed
      // mutation.
      const replayed = _performReplay(streamerSlot);
      _replayedCount[streamerSlot] = replayed;
      _transition(streamerSlot, REPLAY_STATE.SETTLING, nowS);
      return true;
    }

    case REPLAY_STATE.SETTLING: {
      // Wait for SETTLING_DWELL_S so the material and lighting bridges
      // have time to finish applying the replay events.
      if (stateAge < SETTLING_DWELL_S) {
        return false;
      }
      // Transition to DONE.
      _transition(streamerSlot, REPLAY_STATE.DONE, nowS);
      _replayComplete[streamerSlot] = 1;
      return true;
    }

    case REPLAY_STATE.DONE:
      return false;
  }
  return false;
}

function _transition(streamerSlot, newState, nowS) {
  const oldState = _replayState[streamerSlot];
  if (oldState === newState) return;
  _replayState[streamerSlot] = newState;
  _stateEnteredS[streamerSlot] = nowS;
}

// Read the stored mutation count for a chunk. Delegates to 341's public
// API. If 341 doesn't expose the count, we fall back to 0.
function _getStoredMutationCount(streamerSlot) {
  if (LandscapeChunkPersistence && typeof LandscapeChunkPersistence.getMutationCount === 'function') {
    return LandscapeChunkPersistence.getMutationCount(streamerSlot);
  }
  // Fallback: assume 0. If 341 is properly initialised, this path is
  // never taken.
  return 0;
}

// Perform the replay for a chunk. Calls 341's replayIntoChunk to emit the
// replay events, then applies the material and lighting overrides to each
// replayed mutation. Returns the number of mutations replayed.
function _performReplay(streamerSlot) {
  // Phase 1: read the stored mutation list so we know what we're applying
  // overrides for.
  const n = _getStoredMutationCount(streamerSlot);
  if (n === 0) return 0;
  const read = LandscapeChunkPersistence.readMutations
    ? LandscapeChunkPersistence.readMutations(streamerSlot, _mutTypes, _mutPositions, _mutRadii, 256)
    : 0;

  // Phase 2: call 341's replayIntoChunk to emit the per-mutation events.
  // The material and lighting bridges subscribe to those events and apply
  // the overrides in their own listeners.
  if (LandscapeChunkPersistence && typeof LandscapeChunkPersistence.replayIntoChunk === 'function') {
    LandscapeChunkPersistence.replayIntoChunk(streamerSlot);
  }

  // Phase 3: also emit a single aggregate REPLAY_COMPLETED event so
  // consumers that don't subscribe to individual mutation events can
  // refresh once per chunk.
  _dispatcher.emit(EVENT_TYPE.REPLAY_COMPLETED, {
    streamerSlot,
    mutationCount: read,
    tick: BiomeBlendSystem.elapsedSimSeconds
  });

  return read;
}

// ══════════════════════════════════════════════════════════════════
// ─── PUBLIC API ─────────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════
export const LandscapeChunkMutationReplay = Object.freeze({
  // ─── Configuration ─────────────────────────────────────────
  REPLAY_STATE,
  tickChunkBudget: DEFAULT_TICK_CHUNK_BUDGET,
  tickCpuBudgetMs: DEFAULT_TICK_CPU_BUDGET_MS,
  stabilityDwellS: STABILITY_DWELL_S,
  settlingDwellS: SETTLING_DWELL_S,

  /**
   * Initialise the replay orchestrator. Called once by 361 or 362 at
   * runtime bootstrap. Subscribes to the streamer's STREAMED_IN and
   * STREAMED_OUT events.
   */
  init() {
    _dispatcher.on(EVENT_TYPE.CHUNK_STREAMED_IN, _onStreamedIn);
    _dispatcher.on(EVENT_TYPE.CHUNK_STREAMED_OUT, _onStreamedOut);
    _dispatcher.emit(EVENT_TYPE.REPLAY_INITIALIZED, {
      tickChunkBudget: DEFAULT_TICK_CHUNK_BUDGET
    });
  },

  /**
   * The 10 Hz consumer entry point. Called by 308_ContextConsumerTiers.
   */
  run(frame, tick, dt) {
    const t0 = performanceNow();

    const nowS = BiomeBlendSystem.elapsedSimSeconds;

    // ─── 1. Advance the replay state machine for queued chunks ──
    let processed = 0;
    let replayed = 0;
    let completed = 0;
    let eventsThisTick = 0;

    for (let b = 0; b < this.tickChunkBudget; b++) {
      // Peek the head of the queue. If it's empty, break.
      if (_queueHead === _queueTail) break;

      const streamerSlot = _queue[_queueHead];
      if (streamerSlot < 0) {
        _queueHead = (_queueHead + 1) % MAX_QUEUE_SIZE;
        continue;
      }

      // Skip chunks that are no longer active (streamed out before they
      // could be replayed).
      if (!_chunkActive[streamerSlot]) {
        _queue[_queueHead] = -1;
        _queueHead = (_queueHead + 1) % MAX_QUEUE_SIZE;
        continue;
      }

      // Skip chunks that are fully occluded: we don't want to replay a
      // chunk the player cannot see, because the replay work would be
      // wasted and the chunk might be streamed out before the player
      // ever looks at it.
      if (LandscapeChunkOcclusion && typeof LandscapeChunkOcclusion.isFullyOccluded === 'function') {
        if (LandscapeChunkOcclusion.isFullyOccluded(streamerSlot)) {
          // Leave the chunk in the queue; it will be re-attempted on the
          // next tick.
          processed++;
          if ((performanceNow() - t0) > this.tickCpuBudgetMs) break;
          continue;
        }
      }

      // Advance the chunk's state machine.
      const stateBefore = _replayState[streamerSlot];
      const stateChanged = _advanceChunk(streamerSlot, nowS, dt);
      const stateAfter = _replayState[streamerSlot];

      if (stateChanged) {
        if (stateAfter === REPLAY_STATE.REPLAYING) {
          replayed++;
          eventsThisTick += _totalMutationCount[streamerSlot];
        }
        if (stateAfter === REPLAY_STATE.DONE) {
          completed++;
          // Remove the chunk from the queue.
          _queue[_queueHead] = -1;
          _queueHead = (_queueHead + 1) % MAX_QUEUE_SIZE;
        }
      }

      processed++;

      // Check the per-tick CPU budget.
      if ((performanceNow() - t0) > this.tickCpuBudgetMs) break;
    }

    _lastProcessed = processed;
    _lastReplayed = replayed;
    _lastCompleted = completed;
    _lastTickDurationMs = performanceNow() - t0;
    _lastQueueDepth = (_queueTail - _queueHead + MAX_QUEUE_SIZE) % MAX_QUEUE_SIZE;
    _lastEventsOverflow = eventsThisTick > MAX_REPLAY_EVENTS_PER_TICK;

    // ─── 2. Emit the aggregate event ────────────────────────
    if (processed > 0) {
      _dispatcher.emit(EVENT_TYPE.REPLAY_UPDATED, {
        tick,
        processed,
        replayed,
        completed,
        queueDepth: _lastQueueDepth,
        durationMs: _lastTickDurationMs,
        eventsOverflow: _lastEventsOverflow
      });
    }
  },

  /**
   * Query whether a chunk's replay is complete. Downstream consumers that
   * are about to touch a freshly streamed chunk must check this before
   * assuming the chunk is in its final state.
   *
   * @param {number} streamerSlot
   * @returns {boolean}
   */
  isReplayComplete(streamerSlot) {
    if (streamerSlot < 0 || streamerSlot >= MAX_TRACKED_CHUNKS) return false;
    return _replayComplete[streamerSlot] === 1;
  },

  /**
   * Query a chunk's current replay state.
   */
  getReplayState(streamerSlot) {
    if (streamerSlot < 0 || streamerSlot >= MAX_TRACKED_CHUNKS) return REPLAY_STATE.NOT_QUEUED;
    return _replayState[streamerSlot];
  },

  /**
   * Read the replay state for a chunk. Writes into the caller's
   * preallocated output object.
   */
  readReplayState(streamerSlot, out) {
    if (streamerSlot < 0 || streamerSlot >= MAX_TRACKED_CHUNKS) return false;
    out.state = _replayState[streamerSlot];
    out.stateAgeS = BiomeBlendSystem.elapsedSimSeconds - _stateEnteredS[streamerSlot];
    out.totalMutationCount = _totalMutationCount[streamerSlot];
    out.replayedCount = _replayedCount[streamerSlot];
    out.replayComplete = _replayComplete[streamerSlot] === 1;
    return true;
  },

  /**
   * Notify the orchestrator that a chunk's geometry version has changed.
   * Called by 337_LandscapeChunkStreamer after each regeneration pass so
   * the orchestrator can detect a mid-regeneration replay and defer it.
   */
  notifyGeometryChange(streamerSlot, newVersion) {
    if (streamerSlot < 0 || streamerSlot >= MAX_TRACKED_CHUNKS) return;
    if (!_chunkActive[streamerSlot]) return;
    _currentGeometryVersion[streamerSlot] = newVersion | 0;
    _lastGeometryChangeS[streamerSlot] = BiomeBlendSystem.elapsedSimSeconds;
    // If the chunk was in AWAITING_STABILITY, restart the dwell timer by
    // re-entering AWAITING_STABILITY (which resets _stateEnteredS).
    if (_replayState[streamerSlot] === REPLAY_STATE.AWAITING_STABILITY) {
      _stateEnteredS[streamerSlot] = BiomeBlendSystem.elapsedSimSeconds;
    }
  },

  /**
   * Force a chunk's replay to be re-attempted. Used by 341's diagnostics
   * and by 357's event budget collapse when a stored mutation list needs
   * to be replayed again.
   */
  requeueChunk(streamerSlot) {
    if (streamerSlot < 0 || streamerSlot >= MAX_TRACKED_CHUNKS) return;
    if (!_chunkActive[streamerSlot]) return;
    _replayState[streamerSlot] = REPLAY_STATE.QUEUED;
    _stateEnteredS[streamerSlot] = BiomeBlendSystem.elapsedSimSeconds;
    _replayComplete[streamerSlot] = 0;
    // Re-enqueue the chunk.
    if (((_queueTail + 1) % MAX_QUEUE_SIZE) !== _queueHead) {
      _queue[_queueTail] = streamerSlot;
      _queueTail = (_queueTail + 1) % MAX_QUEUE_SIZE;
    }
  },

  // ─── Diagnostics ─────────────────────────────────────────
  get lastProcessed() { return _lastProcessed; },
  get lastReplayed() { return _lastReplayed; },
  get lastCompleted() { return _lastCompleted; },
  get lastTickDurationMs() { return _lastTickDurationMs; },
  get lastQueueDepth() { return _lastQueueDepth; },
  get lastEventsOverflow() { return _lastEventsOverflow; },
  get activeChunks() {
    let n = 0;
    for (let i = 0; i < MAX_TRACKED_CHUNKS; i++) if (_chunkActive[i]) n++;
    return n;
  },
  get queuedChunks() { return _lastQueueDepth; }
});

// Performance-now shim that works in every JS environment.
function performanceNow() {
  if (typeof performance !== 'undefined' && performance.now) return performance.now();
  return Date.now();
}

export default LandscapeChunkMutationReplay;